<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Search, Upload, MoreFilled, Document, FolderAdd, Refresh, View, Delete, Link, DataAnalysis } from '@element-plus/icons-vue'
import { service } from '@/services/service'
import type { Material, ToolId } from '@/domain/types'
import { tools } from '@/domain/tools'
import { useFileBrowser, messageOf, formatSize } from '@/composables/useFileBrowser'
import { mergeSelection, togglePageSelection, reconcileSelection } from '@/domain/fileSelection'
import FolderNavigator from '@/components/library/FolderNavigator.vue'
import SourcePreview from '@/components/SourcePreview.vue'
import UploadDialog from '@/components/UploadDialog.vue'
import AttachmentDialog from '@/components/AttachmentDialog.vue'
const router=useRouter(),browser=useFileBrowser()
const {query,folders,files,total,loading,error,folderLoading,folderError,currentPath,currentFolder}=browser
const selected=ref<Material[]>([]),resolving=ref(false),busy=ref(false),composition=ref(false)
const uploadOpen=ref(false),previewOpen=ref(false),previewFile=ref<Material|null>(null),selectedOpen=ref(false),selectedRemovals=ref<string[]>([]),selectedKeyword=ref(''),selectedPage=ref(1)
const attachmentOpen=ref(false),attachmentFile=ref<Material|null>(null),attachments=ref<Material[]>([])
const ids=computed(()=>new Set(selected.value.map(file=>file.id)))
const pageAll=computed(()=>files.value.length>0&&files.value.every(file=>ids.value.has(file.id)))
const pagePartial=computed(()=>!pageAll.value&&files.value.some(file=>ids.value.has(file.id)))
const parsedCount=computed(()=>selected.value.filter(file=>file.parseStatus==='parsed'&&file.canAnalyze!==false).length)
const selectedFiltered=computed(()=>selected.value.filter(file=>file.name.toLowerCase().includes(selectedKeyword.value.trim().toLowerCase())))
const selectedShown=computed(()=>selectedFiltered.value.slice((selectedPage.value-1)*15,selectedPage.value*15))
const groups=[{name:'通用分析',ids:['extract','word','theme','timeline','risk']},{name:'专题分析',ids:['meeting','bidding','contract','prepaid']},{name:'台账分析',ids:['engineering','association']}]
function toggle(file:Material,value:boolean){selected.value=value?mergeSelection(selected.value,[file]):selected.value.filter(item=>item.id!==file.id)}
function selectPage(value:boolean){selected.value=togglePageSelection(selected.value,files.value,value)}
async function scopeSelection(mode:'all'|'remove'|'page'){if(mode==='page'){selected.value=[...files.value];return}resolving.value=true;try{const scoped=await service.resolveSelection({...query,page:1});const scopedIds=new Set(scoped.map((file:Material)=>file.id));if(mode==='all')selected.value=mergeSelection(selected.value,scoped);else{selected.value=selected.value.filter(file=>!scopedIds.has(file.id))}ElMessage.success(mode==='all'?`本范围已选 ${scoped.length} 份资料`:'已更新本范围选择')}catch(e){ElMessage.error(messageOf(e))}finally{resolving.value=false}}
function preview(file:Material){previewFile.value=file;previewOpen.value=true}
async function analyze(tool:ToolId){let available:Material[];try{const checked=reconcileSelection(selected.value,await service.getMaterials(selected.value.map(file=>file.id)));available=checked.files;if(checked.removed.length){selected.value=checked.files;ElMessage.warning('部分资料的状态或权限已变化，已更新选集，请核对后重新选择分析工具。');return}}catch(e){ElMessage.error(messageOf(e));return}if(selected.value.length&&!available.length){ElMessage.warning('请先解析所选资料，解析完成后即可分析。');return}if(available.length<selected.value.length)ElMessage.info(`仅带入 ${available.length} 份解析完成的资料`);sessionStorage.setItem('audit:selected-files',JSON.stringify(available));await router.push(`/tool/${tool}`)}
async function parseSelected(){const pending=selected.value.filter(file=>file.parseStatus==='unparsed'||file.parseStatus==='failed');if(!pending.length){ElMessage.info('所选资料均已解析或正在解析。');return}busy.value=true;try{await service.parseFiles(pending.map(file=>file.id));ElMessage.success(`已提交 ${pending.length} 份资料进行解析`);await browser.loadFiles();selected.value=selected.value.map(file=>files.value.find(item=>item.id===file.id)||file)}catch(e){ElMessage.error(messageOf(e))}finally{busy.value=false}}
async function deleteSelected(){if(!selected.value.length)return;try{await ElMessageBox.confirm(`将从资料库删除 ${selected.value.length} 份文件。请确认这些资料不再需要。`,'删除资料',{confirmButtonText:'删除',cancelButtonText:'取消',type:'warning'});busy.value=true;await service.deleteFiles(selected.value.map(file=>file.id));selected.value=[];await browser.loadFiles();ElMessage.success('资料已删除')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(messageOf(e))}finally{busy.value=false}}
async function folderAction(action:string){try{if(action==='create'){const {value}=await ElMessageBox.prompt('请输入文件夹名称','新建文件夹',{inputPlaceholder:'文件夹名称',inputValidator:v=>!!v?.trim()&&!/[\\/]/.test(v)||'请输入有效名称',confirmButtonText:'创建',cancelButtonText:'取消'});await service.createFolder(value.trim(),query.folderId,query.space)}else if(action==='rename'){if(!currentFolder.value)return;const {value}=await ElMessageBox.prompt('请输入新的文件夹名称','重命名',{inputValue:currentFolder.value.name,inputValidator:v=>!!v?.trim()&&!/[\\/]/.test(v)||'请输入有效名称',confirmButtonText:'保存',cancelButtonText:'取消'});await service.renameFolder(currentFolder.value.id,value.trim())}else if(action==='delete'){if(!currentFolder.value)return;await ElMessageBox.confirm(`删除“${currentFolder.value.name}”目录？该操作可能影响其中的资料。`,'删除目录',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});await service.deleteFolder(currentFolder.value.id);query.folderId=undefined}await browser.initialize()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(messageOf(e))}}
async function openAttachments(file:Material){try{attachmentFile.value=file;attachments.value=file.attachmentIds?.length?await service.getMaterials(file.attachmentIds):[];attachmentOpen.value=true}catch(e){ElMessage.error(messageOf(e))}}
async function saveAttachments(values:Material[]){if(!attachmentFile.value)return;try{await service.saveAttachments(attachmentFile.value.id,values.map(file=>file.id));attachmentFile.value.attachmentIds=values.map(file=>file.id);ElMessage.success('附件关联已保存');await browser.loadFiles()}catch(e){ElMessage.error(messageOf(e))}}
function batchRemove(){const removed=new Set(selectedRemovals.value);selected.value=selected.value.filter(file=>!removed.has(file.id));selectedRemovals.value=[];selectedPage.value=Math.min(selectedPage.value,Math.max(1,Math.ceil(selectedFiltered.value.length/15)))}
onMounted(browser.initialize)
</script>
<template>
 <div class="library-page">
  <FolderNavigator :folders="folders" :space="query.space" :current-id="query.folderId" :loading="folderLoading" :error="folderError" @space="browser.changeSpace" @select="browser.chooseFolder" @refresh="browser.loadFolders"/>
  <main class="library-main">
   <div class="library-location"><div><span class="muted">当前目录</span><strong :title="currentPath">{{currentPath}}</strong></div><el-checkbox v-model="query.includeDescendants" @change="browser.search">包含下级文件夹</el-checkbox></div>
   <div class="library-toolbar"><el-input v-model="query.keyword" clearable :prefix-icon="Search" placeholder="查找文件" aria-label="查找文件" @compositionstart="composition=true" @compositionend="composition=false" @keydown.enter="!composition&&!$event.isComposing&&browser.search()" @clear="browser.search"/><el-button @click="browser.search">查询</el-button><el-select v-model="query.parseStatus" clearable placeholder="解析状态" aria-label="筛选解析状态" @change="browser.search"><el-option value="parsed" label="解析完成"/><el-option value="unparsed" label="未解析"/><el-option value="parsing" label="解析中"/><el-option value="failed" label="解析失败"/></el-select><el-button type="primary" :icon="Upload" :disabled="!query.folderId||currentFolder?.canManage===false" :title="!query.folderId?'请先选择上传目录':''" @click="uploadOpen=true">上传</el-button><el-dropdown @command="folderAction"><el-button :icon="MoreFilled" aria-label="目录操作">更多</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="create" :icon="FolderAdd">新建文件夹</el-dropdown-item><el-dropdown-item command="rename" :disabled="!currentFolder||currentFolder.canManage===false">重命名目录</el-dropdown-item><el-dropdown-item command="delete" divided :disabled="!currentFolder||currentFolder.canManage===false">删除目录</el-dropdown-item></el-dropdown-menu></template></el-dropdown><el-button text :icon="Refresh" aria-label="刷新资料" title="刷新资料" @click="browser.loadFiles"/></div>
   <div class="library-select-scope"><span>已选 <strong>{{selected.length}}</strong> 份 · 解析完成 {{parsedCount}} 份 <el-button v-if="selected.length" link type="primary" @click="selectedOpen=true">查看已选</el-button></span><div><el-button link type="primary" :loading="resolving" :disabled="loading||!total" @click="scopeSelection('all')">选择全部页</el-button><el-button v-if="selected.length" link :disabled="resolving" @click="scopeSelection('page')">仅保留本页</el-button><el-button v-if="selected.length" link :disabled="resolving" @click="scopeSelection('remove')">取消本范围选择</el-button></div></div>
   <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
   <el-table v-loading="loading" :data="files" row-key="id" height="100%" class="library-table" empty-text="当前目录暂无资料，选择目录后可上传文件或文件夹">
    <el-table-column width="76"><template #header><el-checkbox :model-value="pageAll" :indeterminate="pagePartial" :disabled="!files.length" aria-label="选择本页" @change="selectPage(Boolean($event))">本页</el-checkbox></template><template #default="{row}"><el-checkbox :model-value="ids.has(row.id)" :aria-label="`选择 ${row.name}`" @change="toggle(row,Boolean($event))"/></template></el-table-column>
    <el-table-column label="文件名称" min-width="250" show-overflow-tooltip><template #default="{row}"><button class="file-open" :title="row.name" @click="preview(row)"><el-icon><Document/></el-icon><span>{{row.name}}</span></button><small v-if="query.includeDescendants||!query.folderId" class="library-file-path">{{row.path}}</small></template></el-table-column>
    <el-table-column label="解析状态" width="110"><template #default="{row}"><span :class="['parse-badge',row.parseStatus]">{{{parsed:'解析完成',unparsed:'未解析',parsing:'解析中',failed:'解析失败'}[row.parseStatus as string]}}</span></template></el-table-column>
    <el-table-column label="大小" width="100"><template #default="{row}">{{formatSize(row.size)}}</template></el-table-column>
    <el-table-column label="更新时间" min-width="140"><template #default="{row}">{{row.updatedAt?new Date(row.updatedAt).toLocaleDateString('zh-CN'):'—'}}</template></el-table-column>
    <el-table-column label="操作" width="96" fixed="right"><template #default="{row}"><el-button text :icon="View" :aria-label="`预览 ${row.name}`" title="预览" @click="preview(row)"/><el-button text :icon="Link" :aria-label="`关联 ${row.name} 的附件`" title="关联附件" @click="openAttachments(row)"/></template></el-table-column>
   </el-table>
   <div class="library-selection-summary"><div v-if="selected.length"><el-button :loading="busy" @click="parseSelected">解析资料</el-button><el-button text :disabled="busy" @click="deleteSelected">删除</el-button></div></div>
   <el-pagination v-model:current-page="query.page" v-model:page-size="query.size" :total="total" :page-sizes="[20,50,100]" layout="total,prev,pager,next,sizes" @current-change="browser.changePage" @size-change="browser.changeSize"/>
   <div class="mobile-tool-list"><el-select placeholder="选择分析工具" aria-label="选择分析工具" @change="analyze($event)"><el-option v-for="tool in tools" :key="tool.id" :value="tool.id" :label="tool.name"/></el-select></div>
  </main>
  <aside class="library-toolbox"><header><el-icon><DataAnalysis/></el-icon><strong>分析工具</strong></header><div class="toolbox-scroll"><section v-for="group in groups" :key="group.name"><h3>{{group.name}}</h3><button v-for="tool in tools.filter(t=>group.ids.includes(t.id))" :key="tool.id" class="tool-entry" @click="analyze(tool.id)"><span class="tool-entry-icon"><el-icon><Document/></el-icon></span><span><strong>{{tool.name}}</strong></span><span class="tool-arrow">›</span></button></section></div></aside>
  <UploadDialog v-model="uploadOpen" :folder-id="query.folderId" :space="query.space" :path="currentPath" @uploaded="browser.initialize"/>
  <el-dialog v-model="previewOpen" title="资料预览" width="min(1280px, calc(100vw - 24px))" top="4vh" destroy-on-close><div class="library-preview"><SourcePreview :file="previewFile" :step="false"/></div></el-dialog>
  <AttachmentDialog v-model="attachmentOpen" :file="attachmentFile" :attachments="attachments" :candidates="[...files,...selected]" @confirm="saveAttachments"/>
  <el-dialog v-model="selectedOpen" title="已选资料" width="min(1040px, calc(100vw - 28px))"><div class="selected-dialog-toolbar"><el-input v-model="selectedKeyword" :prefix-icon="Search" placeholder="查找已选文件" aria-label="查找已选文件" clearable @input="selectedPage=1"/><span>共 <strong>{{selected.length}}</strong> 份</span></div><el-table :data="selectedShown" row-key="id" max-height="430" @selection-change="selectedRemovals=$event.map((file:Material)=>file.id)"><el-table-column type="selection" width="50"/><el-table-column prop="name" label="文件名称" min-width="250" show-overflow-tooltip/><el-table-column prop="owner" label="所有者" width="130"/><el-table-column prop="path" label="目录" min-width="200" show-overflow-tooltip/><el-table-column label="操作" width="70"><template #default="{row}"><el-button link type="danger" @click="toggle(row,false)">移除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="selectedPage" :page-size="15" :total="selectedFiltered.length" layout="total,prev,pager,next"/><template #footer><span class="selected-footer-hint">移除仅取消选择，不删除资料。</span><el-button :disabled="!selectedRemovals.length" @click="batchRemove">批量移除{{selectedRemovals.length?`（${selectedRemovals.length}）`:''}}</el-button><el-button type="primary" @click="selectedOpen=false">关闭</el-button></template></el-dialog>
 </div>
</template>
<style scoped>
.library-page{display:grid;grid-template-columns:260px minmax(0,1fr) 260px;height:100%;min-height:500px;background:#fff;border:1px solid #e6ebf1;border-radius:8px;overflow:hidden}.library-main{min-width:0;display:flex;flex-direction:column;padding:0 16px 14px;gap:10px}.library-location{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:54px;border-bottom:1px solid #e6ebf1;flex-wrap:wrap}.library-location>div{display:flex;align-items:center;min-width:0;gap:10px;font-size:14px}.library-location strong{font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.library-toolbar{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.library-toolbar>.el-input{flex:1;min-width:160px;max-width:340px}.library-toolbar>.el-select{width:130px}.library-toolbar .el-button+.el-button{margin-left:0}.library-select-scope{display:flex;justify-content:space-between;align-items:center;min-height:28px;color:#596b80;font-size:14px;gap:8px;flex-wrap:wrap}.library-select-scope>div{display:flex;gap:12px;align-items:center}.library-select-scope .el-button+.el-button{margin-left:0}.library-table{flex:1;min-height:150px}.file-open{display:flex;align-items:center;gap:8px;max-width:100%;padding:0;border:none;background:none;color:#1e3046;font:inherit;cursor:pointer;text-align:left}.file-open:hover{color:#3269db}.file-open span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.file-open .el-icon{color:#3269db;flex:none}.library-file-path{color:#596b80;font-size:12px}.parse-badge{display:inline-block;padding:3px 7px;border-radius:4px;background:#f1f3f6;color:#596b80;font-size:13px;white-space:nowrap}.parse-badge.parsed{background:#eaf7f2;color:#1d735b}.parse-badge.parsing{background:#eef4ff;color:#2555b4}.parse-badge.failed{background:#fceeee;color:#a33e3e}.library-selection-summary{display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:48px;border-top:1px solid #e6ebf1;font-size:14px;color:#596b80}.library-selection-summary>div{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.library-selection-summary strong{color:#2555b4;font-size:17px}.el-pagination{justify-content:flex-end;flex-wrap:wrap}.library-toolbox{border-left:1px solid #e6ebf1;display:flex;flex-direction:column;min-width:0}.library-toolbox header{display:flex;align-items:center;gap:8px;padding:0 20px;min-height:54px;border-bottom:1px solid #e6ebf1;font-size:17px}.library-toolbox header .el-icon{color:#3269db}.toolbox-scroll{overflow:auto;padding:4px 12px 16px}.toolbox-scroll h3{font-size:13px;font-weight:500;color:#596b80;padding:12px 8px 4px;margin:0}.toolbox-scroll section+section{border-top:1px solid #e6ebf1;margin-top:8px}.tool-entry{display:flex;gap:12px;align-items:center;width:100%;min-height:49px;padding:8px;border:none;background:none;border-radius:7px;cursor:pointer;text-align:left;font:inherit;color:#1e3046}.tool-entry:hover{background:#eef4ff}.tool-entry strong{font-size:14px;font-weight:500}.tool-entry-icon{display:flex;align-items:center;justify-content:center;width:29px;height:31px;color:#3269db;background:#eef4ff;border-radius:7px;flex:none}.tool-arrow{margin-left:auto;color:#596b80}.library-preview{height:74vh}.library-table :deep(.el-button.is-text){padding:4px;min-width:28px}.library-table :deep(.el-button+.el-button){margin-left:0}.library-table :deep(.el-table__cell){padding:11px 0;font-size:14px}.selected-dialog-toolbar{display:flex;gap:15px;align-items:center;margin-bottom:14px}.selected-dialog-toolbar .el-input{max-width:400px}.selected-footer-hint{float:left;line-height:36px;font-size:14px;color:#596b80}.mobile-tool-list{display:none}.muted{color:#596b80;white-space:nowrap}
@media(max-width:1240px){.library-page{grid-template-columns:230px minmax(0,1fr) 220px}.library-main{padding:0 12px 12px}.library-toolbar>.el-select{width:112px}.library-toolbar>.el-input{min-width:140px}.tool-entry{gap:8px}.library-toolbox header{padding:0 16px}}
@media(max-width:1000px){.library-page{grid-template-columns:220px minmax(0,1fr)}.library-toolbox{display:none}.mobile-tool-list{display:block}.mobile-tool-list .el-select{max-width:260px}}
@media(max-width:620px){.library-page{display:flex;flex-direction:column;min-height:650px}.library-page>.directory-nav{max-height:210px;flex:none;border-bottom:1px solid #e6ebf1}.library-main{flex:1;min-height:0}.library-selection-summary{align-items:flex-start;flex-wrap:wrap;padding-top:8px}.library-location{padding:8px 0}.library-location>div{max-width:100%}.library-main :deep(.el-pagination__sizes){display:none}.selected-footer-hint{display:none}}
</style>
